import{_ as d,o as e,c as o,a3 as a}from"./chunks/framework.BLaSdaBb.js";const g=JSON.parse('{"title":"实体基类","description":"","frontmatter":{},"headers":[],"relativePath":"backend/entity.md","filePath":"backend/entity.md","lastUpdated":1786258579000}'),c={name:"backend/entity.md"};function s(i,t,r,n,l,h){return e(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="实体基类" tabindex="-1">实体基类 <a class="header-anchor" href="#实体基类" aria-label="Permalink to &quot;实体基类&quot;">​</a></h1><p>新增实体前先读这页：基类怎么选、有哪些列是自动来的、多租户列是什么语义、软删与唯一索引怎么配合、命名和索引有哪些强制规范。选错基类的返工成本很高。</p><p>全部数据表的清单见 <a href="./data-model">数据模型</a>。</p><h2 id="先选对基类" tabindex="-1">先选对基类 <a class="header-anchor" href="#先选对基类" aria-label="Permalink to &quot;先选对基类&quot;">​</a></h2><p>所有 BasicApp 实体都继承 <code>XiHan.BasicApp.Core.Entities</code> 下的基类，它们各自对应框架的 <code>SugarMultiTenant*</code> 系列——<strong>都自带 <code>TenantId</code> 列</strong>。</p><table tabindex="0"><thead><tr><th>基类</th><th>主键</th><th>审计列</th><th>软删</th><th>用在哪</th></tr></thead><tbody><tr><td><code>BasicAppEntity</code></td><td>雪花 <code>long</code></td><td>无</td><td>否</td><td>极简实体、纯关联表</td></tr><tr><td><code>BasicAppEntityWithIdentity</code></td><td>数据库自增 <code>long</code></td><td>无</td><td>否</td><td>需要自增序号的场景</td></tr><tr><td><code>BasicAppCreationEntity</code></td><td>雪花 <code>long</code></td><td>创建三列</td><td>否</td><td><strong>日志 / 流水</strong>等只增不改的表</td></tr><tr><td><code>BasicAppModificationEntity</code></td><td>雪花 <code>long</code></td><td>仅修改三列</td><td>否</td><td>会改但不删的配置类</td></tr><tr><td><code>BasicAppDeletionEntity</code></td><td>雪花 <code>long</code></td><td>仅删除四列</td><td>是</td><td>少见</td></tr><tr><td><strong><code>BasicAppFullAuditedEntity</code></strong></td><td>雪花 <code>long</code></td><td>创建 + 修改 + 删除</td><td><strong>是</strong></td><td><strong>绝大多数业务实体的默认选择</strong></td></tr><tr><td><code>BasicAppAggregateRoot</code></td><td>雪花 <code>long</code></td><td>全套</td><td>是</td><td>聚合根（带领域事件能力）</td></tr></tbody></table><p>选择准则：</p><ul><li><strong>拿不准就用 <code>BasicAppFullAuditedEntity</code></strong>——业务表几乎都需要「谁建的、谁改的、软删可恢复」。</li><li><strong>日志、流水、审计类用 <code>BasicAppCreationEntity</code></strong>：只增不改不删，带上修改/删除列纯属浪费，而且这类表通常还要<strong>按月分表</strong>。</li><li>纯多对多关联表（如 <code>SysUserRole</code>）通常也是创建型（硬删）。</li></ul><h2 id="自动来的列" tabindex="-1">自动来的列 <a class="header-anchor" href="#自动来的列" aria-label="Permalink to &quot;自动来的列&quot;">​</a></h2><h3 id="主键与并发" tabindex="-1">主键与并发 <a class="header-anchor" href="#主键与并发" aria-label="Permalink to &quot;主键与并发&quot;">​</a></h3><table tabindex="0"><thead><tr><th>列</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>Basic_Id</code></td><td><code>bigint</code></td><td><strong>主键</strong>。注意列名是 <code>Basic_Id</code> 不是 <code>Id</code>——手写 SQL / 排查时别找错。默认<strong>非自增</strong>，由应用侧雪花算法生成</td></tr><tr><td><code>Row_Version</code></td><td><code>bigint</code></td><td>乐观并发标识，SqlSugar 的 <code>IsEnableUpdateVersionValidation</code> 生效</td></tr></tbody></table><p>雪花参数在配置节 <code>XiHan:DistributedIds:SnowflakeId</code>。</p><div class="danger custom-block"><p class="custom-block-title">多节点必须逐节点改 <code>WorkerId</code></p><p>两个节点同 <code>WorkerId</code> 会生成<strong>重复主键</strong>，且不会立刻报错——等到唯一约束冲突时数据已经乱了。<code>BaseTime</code> 与位长一经上线不可更改。</p></div><div class="warning custom-block"><p class="custom-block-title">主键在 API 里是字符串</p><p><code>long</code> 经框架的 <code>LongJsonConverter</code> 统一序列化成 JSON <strong>字符串</strong>（避免 JavaScript Number 精度溢出）。前端契约里主键类型是 <code>string</code>，DTO 字段名是 <code>basicId</code>。</p></div><h3 id="审计三件套" tabindex="-1">审计三件套 <a class="header-anchor" href="#审计三件套" aria-label="Permalink to &quot;审计三件套&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>列</th><th>备注</th></tr></thead><tbody><tr><td>创建</td><td><code>Created_Time</code> / <code>Created_Id</code> / <code>Created_By</code></td><td><code>Created_Time</code> 非空；三列都是 <code>IsOnlyIgnoreUpdate</code>（更新时不覆盖）</td></tr><tr><td>修改</td><td><code>Modified_Time</code> / <code>Modified_Id</code> / <code>Modified_By</code></td><td>可空</td></tr><tr><td>删除</td><td><code>Is_Deleted</code> / <code>Deleted_Time</code> / <code>Deleted_Id</code> / <code>Deleted_By</code></td><td><code>Is_Deleted</code> 非空、默认 <code>false</code></td></tr></tbody></table><p>时间列都是 <code>DateTimeOffset</code>，<strong>存储恒为 UTC</strong>，输出时按请求头 <code>X-Timezone</code> 换算。</p><div class="tip custom-block"><p class="custom-block-title">这些列由 AOP 自动注入</p><p>走的是 SqlSugar 的 <code>DataExecuting</code> AOP，<strong>业务代码不要手动赋值</strong>——修改三列会被 AOP 无条件覆盖；创建列只在值为默认值时才填充，手动赋值会留下与实际操作人不符的审计信息。</p></div><div class="warning custom-block"><p class="custom-block-title">别对时间列做单列标量投影</p><p><code>DateTimeOffset</code> 列不要用 <code>Select(x =&gt; x.CreatedTime)</code> 这种单列标量投影——值类型的 <code>ChangeType</code> 路径会在 <code>DateTime</code> → DTO 转换时崩。要整行取实体、走属性绑定。</p></div><h3 id="多租户列" tabindex="-1">多租户列 <a class="header-anchor" href="#多租户列" aria-label="Permalink to &quot;多租户列&quot;">​</a></h3><p><code>Tenant_Id</code>（<code>bigint</code>，<code>IsOnlyIgnoreUpdate</code>）每个实体都有，语义<strong>不是可空的</strong>：</p><ul><li><strong>平台级/全局记录统一 <code>TenantId = 0</code></strong>（「平台租户」占位），<strong>不得使用 NULL</strong>。</li><li>业务租户 Id 从 1 开始，0 号由平台保留。</li><li>判定全局记录一律用 <code>TenantId == 0</code>；需要 <code>IsGlobal</code> 语义时在实体 <code>Expand</code> 里做<strong>派生只读属性</strong> <code>IsGlobal =&gt; TenantId == 0</code>，<strong>不落库</strong>（避免与 <code>TenantId</code> 漂移）。</li><li>合并查询全局 + 私有：<code>WHERE TenantId IN (0, {currentTenantId})</code>。</li><li><code>TenantId</code> 由租户上下文自动注入，<strong>禁止业务代码直接操纵</strong>。</li></ul><div class="danger custom-block"><p class="custom-block-title">读写口径不对称</p><p><strong>读共享、写不共享</strong>——全局过滤器放行 <code>TenantId=0</code> 的行让租户能读到平台数据，但租户上下文里<strong>禁止改写/删除</strong>非本租户行（含全局行）。维护全局数据的唯一入口是平台态（<code>ICurrentTenant.Change(null)</code>）。</p><p>详见 <a href="./multi-tenancy">多租户 SaaS</a>。</p></div><h2 id="软删与唯一索引" tabindex="-1">软删与唯一索引 <a class="header-anchor" href="#软删与唯一索引" aria-label="Permalink to &quot;软删与唯一索引&quot;">​</a></h2><p>支持软删的实体，其<strong>唯一索引（<code>UX_*</code>）末列统一附加 <code>IsDeleted</code></strong>，使唯一性只约束未删除行——软删后可以再建同编码记录。</p><p>代价要知道：<strong>同一编码至多保留一条软删行</strong>。要第二次软删同编码记录，服务层得先物理清理旧的软删行。</p><p>纯创建型（<code>Creation</code>）的关联表与日志表是<strong>硬删</strong>、无 <code>IsDeleted</code>，唯一索引保持原样。</p><h2 id="命名与索引规范" tabindex="-1">命名与索引规范 <a class="header-anchor" href="#命名与索引规范" aria-label="Permalink to &quot;命名与索引规范&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对象</th><th>规范</th><th>示例</th></tr></thead><tbody><tr><td>表名</td><td><code>snake_case</code>，<code>Sys_{名}</code></td><td><code>Sys_User_Department</code></td></tr><tr><td>列名</td><td><code>snake_case</code></td><td><code>Created_Time</code>、<code>Tenant_Id</code></td></tr><tr><td><code>[SugarTable]</code> 命名参数</td><td><strong>无空格</strong></td><td><code>SugarTable(TableName = &quot;...&quot;, TableDescription = &quot;...&quot;)</code></td></tr><tr><td><code>[SugarColumn]</code> 命名参数</td><td><strong>有空格</strong></td><td><code>SugarColumn(ColumnName = &quot;...&quot;, ColumnDescription = &quot;...&quot;)</code></td></tr><tr><td>时间字段</td><td>一律 <code>XxxTime</code>；过期统一 <code>ExpirationTime</code></td><td><code>CreatedTime</code> / <code>ExpirationTime</code></td></tr><tr><td>排序字段</td><td><code>Sort</code></td><td>—</td></tr><tr><td>缩写</td><td><code>OAuth</code> / <code>CSharp</code> 等整体保留</td><td><code>SysOAuthApp</code></td></tr></tbody></table><p><strong>审计三件套索引</strong>（强制）：</p><ul><li>所有具体实体：<code>IX_{table}_TeId_CrTi</code>、<code>IX_{table}_CrId</code></li><li><code>FullAudited</code> / <code>AggregateRoot</code> 额外：<code>IX_{table}_TeId_IsDe</code></li><li>日志类分表实体把 <code>{table}</code> 换成 <code>{split_table}</code></li></ul><h2 id="按月分表" tabindex="-1">按月分表 <a class="header-anchor" href="#按月分表" aria-label="Permalink to &quot;按月分表&quot;">​</a></h2><p>日志与流水类实体用 SqlSugar 的分表能力：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SugarTable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">TableName</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Sys_Access_Log_{year}{month}{day}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">TableDescription</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;系统访问日志表&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SplitTable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(SplitType.Month)]</span></span></code></pre></div><p>物理表名形如 <code>Sys_Access_Log_20260801</code>。查询分表数据要走 SqlSugar 的分表 API（按时间范围定位物理表），<strong>不能当普通表直接查</strong>。</p><p>哪些表分了表见 <a href="./data-model#日志-均按月分表">数据模型</a>。</p><h2 id="实体分文件约定" tabindex="-1">实体分文件约定 <a class="header-anchor" href="#实体分文件约定" aria-label="Permalink to &quot;实体分文件约定&quot;">​</a></h2><p>一个实体通常拆成三个文件（<code>partial</code>）：</p><table tabindex="0"><thead><tr><th>文件</th><th>内容</th></tr></thead><tbody><tr><td><code>Domain/Entities/SysXxx.cs</code></td><td>主体：<code>[SugarTable]</code> + <code>[SugarIndex]</code> + 落库字段</td></tr><tr><td><code>Domain/Entities/Expands/SysXxx.Expand.cs</code></td><td><strong>不落库</strong>的派生属性（<code>[SugarColumn(IsIgnore = true)]</code>），如 <code>IsGlobal</code>、显示名</td></tr><tr><td><code>Domain/Entities/Aggregates/SysXxx.Aggregate.cs</code></td><td>聚合行为（少数实体才有，如 <code>SysTenant</code> / <code>SysConstraintRule</code>）</td></tr></tbody></table><p>枚举放 <code>Domain/Entities/Enums/SysXxx.Enum.cs</code>。</p><div class="tip custom-block"><p class="custom-block-title">生成的代码不焊外键</p><p>代码生成器不产出 <code>Navigate</code> / <code>LEFT JOIN</code> / 显示属性 / 物理外键，跨表关联一律由业务层手写。见 <a href="./code-generation">代码生成</a>。</p></div><h2 id="加一个实体的清单" tabindex="-1">加一个实体的清单 <a class="header-anchor" href="#加一个实体的清单" aria-label="Permalink to &quot;加一个实体的清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>做什么</th></tr></thead><tbody><tr><td>1</td><td>选基类（默认 <code>BasicAppFullAuditedEntity</code>）</td></tr><tr><td>2</td><td>写 <code>[SugarTable]</code> + 字段 + <code>[SugarIndex]</code>（含审计三件套索引）</td></tr><tr><td>3</td><td>派生属性放 <code>Expands/</code>，枚举放 <code>Enums/</code></td></tr><tr><td>4</td><td>加仓储接口与实现（继承 <code>SaasRepository</code>，自动注册）</td></tr><tr><td>5</td><td>全新库由 CodeFirst 建表；存量库在 <code>WebHost/UpdateScripts/{version}.sql</code> 补建表/列/索引脚本</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./database">数据库配置</a>：连接、初始化开关、主从、分表查询</li><li><a href="./data-model">数据模型</a>：全部数据表清单</li><li><a href="./development">开发流程</a>：加一个完整功能纵切片</li><li><a href="https://framework.docs.xihanfun.com/packages/data" target="_blank" rel="noreferrer">框架 · Data 包</a>：仓储、查询过滤器、AOP 的框架实现</li></ul>`,45)])])}const u=d(c,[["render",s]]);export{g as __pageData,u as default};
